css:
.lumieresim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2c2722;
    background: linear-gradient(165deg, #faf6ef 0%, #f3ece0 55%, #efe6d6 100%);
    border-radius: 18px;
}

.lumieresim-container * {
    box-sizing: border-box;
}

.lumieresim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2c2722 0%, #3d342b 55%, #6b4a35 100%);
    color: #faf3e8;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #4a3d31;
    box-shadow: 0 14px 36px rgba(58, 44, 32, 0.28);
}

.lumieresim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fbf4ea;
}

.lumieresim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e9a76b;
    background: rgba(233, 167, 107, 0.14);
    border: 1px solid rgba(233, 167, 107, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.lumieresim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #e6d8c5;
}

.lumieresim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6e5f4f;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.lumieresim-period-counter #currentDay,
.lumieresim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5642e;
}

.lumieresim-round-name {
    background: rgba(181, 100, 46, 0.12);
    color: #b5642e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.lumieresim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a2b;
    background: rgba(233, 167, 107, 0.18);
    border: 1px solid rgba(181, 100, 46, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.lumieresim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.lumieresim-status-card {
    background: #fffdf9;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6dcca;
    box-shadow: 0 6px 16px rgba(108, 80, 50, 0.10);
    border-top: 4px solid #c9b79a;
}

.lumieresim-card-desire { border-top-color: #b5642e; }
.lumieresim-card-personal { border-top-color: #4f8a6b; }
.lumieresim-card-societal { border-top-color: #4a7fa6; }
.lumieresim-card-payback { border-top-color: #8a5a2b; }

.lumieresim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #9a8a73;
}

.lumieresim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2c2722;
    font-variant-numeric: tabular-nums;
}

.lumieresim-card-desire .lumieresim-value { color: #b5642e; }
.lumieresim-card-personal .lumieresim-value { color: #4f8a6b; }
.lumieresim-card-societal .lumieresim-value { color: #4a7fa6; }
.lumieresim-card-payback .lumieresim-value { color: #8a5a2b; }

.lumieresim-sublabel {
    font-size: 0.76rem;
    color: #8a7c66;
    line-height: 1.38;
}

.lumieresim-desire-high { border-top-color: #4f8a6b; }
.lumieresim-desire-high .lumieresim-value { color: #4f8a6b; }
.lumieresim-desire-low { border-top-color: #c2402d; }
.lumieresim-desire-low .lumieresim-value { color: #c2402d; }

.lumieresim-payback-good { border-top-color: #4f8a6b; }
.lumieresim-payback-good .lumieresim-value { color: #4f8a6b; }
.lumieresim-payback-bad { border-top-color: #c2402d; }
.lumieresim-payback-bad .lumieresim-value { color: #c2402d; }

.lumieresim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf9;
    border: 1px solid #e6dcca;
    color: #4a3d31;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.lumieresim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b5642e;
}

.lumieresim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf9;
    border-left: 5px solid #b5642e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(108, 80, 50, 0.08);
}

.lumieresim-briefing-icon {
    font-size: 1.7rem;
    line-height: 1.2;
    color: #b5642e;
}

.lumieresim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #2c2722;
    margin-bottom: 6px;
}

.lumieresim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #4a3d31;
}

.lumieresim-briefing-text strong { color: #b5642e; }
.lumieresim-briefing-text em { color: #8a5a2b; font-style: italic; }

.lumieresim-controls {
    background: #fffdf9;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6dcca;
    box-shadow: 0 6px 16px rgba(108, 80, 50, 0.08);
}

.lumieresim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2c2722;
    border-bottom: 2px solid #ece2d0;
    padding-bottom: 8px;
}

.lumieresim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3d342b;
    margin: 14px 0 6px;
}

.lumieresim-container select,
.lumieresim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8cab2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf9;
    color: #2c2722;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.lumieresim-container select:focus,
.lumieresim-container input[type="number"]:focus {
    outline: none;
    border-color: #b5642e;
    box-shadow: 0 0 0 3px rgba(181, 100, 46, 0.16);
}

.lumieresim-container select option {
    background-color: #fffdf9;
    color: #2c2722;
}

.lumieresim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5642e;
}

.lumieresim-range-readout,
.lumieresim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6e5f4f;
    margin-top: 4px;
}

.lumieresim-range-readout span:last-child,
.lumieresim-alloc-readout span:nth-child(2) {
    color: #b5642e;
    font-weight: 800;
}

.lumieresim-hint {
    font-size: 0.8rem;
    color: #8a7c66;
    margin-top: 4px;
    line-height: 1.45;
}

.lumieresim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.lumieresim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f0e4;
    border: 1px solid #e2d6c0;
    border-radius: 9px;
    padding: 8px 12px;
}

.lumieresim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3d342b;
}

.lumieresim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.lumieresim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.lumieresim-container .btn-primary {
    background: linear-gradient(135deg, #8a4a22 0%, #b5642e 55%, #e9a76b 100%);
    border: none;
    color: #fff7ec;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(138, 74, 34, 0.30);
}

.lumieresim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.lumieresim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8cab2;
    color: #6e5f4f;
    background: transparent;
}

.lumieresim-coach {
    background: linear-gradient(160deg, #2c2722 0%, #3d342b 100%);
    color: #ece0cf;
    border: 1px solid #4a3d31;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(58, 44, 32, 0.22);
}

.lumieresim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9a76b;
    margin-bottom: 8px;
}

.lumieresim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.lumieresim-coach-body strong { color: #e9a76b; }
.lumieresim-coach-body em { color: #d7b58c; font-style: italic; }

.lumieresim-history,
.lumieresim-chart {
    background: #fffdf9;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6dcca;
    box-shadow: 0 6px 16px rgba(108, 80, 50, 0.08);
}

.lumieresim-history h3,
.lumieresim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2c2722;
}

.lumieresim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3d342b;
}

.lumieresim-container table#usfHistoryTable th {
    background: #f3ead9;
    color: #8a5a2b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d6c0;
}

.lumieresim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ede3d2;
    color: #4a3d31;
}

.lumieresim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf5ec;
}

.lumieresim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .lumieresim-container {
        padding: 14px;
    }
    .lumieresim-header h1 {
        font-size: 1.75rem;
    }
    .lumieresim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .lumieresim-value {
        font-size: 2rem;
    }
    .lumieresim-clock {
        margin-left: 0;
    }
    .lumieresim-period-counter {
        font-size: 0.88rem;
    }
    .lumieresim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .lumieresim-alloc-row {
        flex-wrap: wrap;
    }
    .lumieresim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .lumieresim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .lum-cm-*, warm terracotta/gold) ── */
.lum-cm { margin-top: 8px; }
.lum-cm-incomplete { text-align: center; color: #7a6a55; font-size: 1rem; padding: 18px; }
.lum-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.lum-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #7c3a24 0%, #b5623a 55%, #d9a441 140%); color: #fff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(124,58,36,0.28); }
.lum-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.lum-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.lum-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f3e0b0; }
.lum-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fff; border: 1px solid #e7ddce; border-left: 5px solid #b5623a; border-radius: 14px; padding: 16px 20px; }
.lum-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #7a6a55; }
.lum-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #7c3a24; line-height: 1.15; }
.lum-cm-section { margin-bottom: 16px; }
.lum-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #7a6a55; margin-bottom: 8px; }
.lum-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.lum-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.lum-cm-ok { background: #eef6ec; color: #2f6d33; border-color: #b7ddb0; }
.lum-cm-no { background: #fbecea; color: #a5382a; border-color: #eec4bd; }
.lum-cm-ico { font-weight: 800; }
.lum-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.lum-cm-kpi { background: #faf6ef; border: 1px solid #ece1d0; border-radius: 12px; padding: 12px 14px; text-align: center; }
.lum-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #7c3a24; }
.lum-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #7a6a55; }
.lum-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #a2917b; }
.lum-cm-insights { margin: 0; padding-left: 18px; }
.lum-cm-insights li { font-size: 0.9rem; color: #4a3f30; margin-bottom: 6px; line-height: 1.45; }

