(function() {
    'use strict';

    class LumiereAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Design for Longevity`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lumière Living, Lda. — Porto, EUR).
            this.LAUNCH_BUDGET = 4.0;        // EUR 4.0M board-approved launch budget
            this.INCLUSIVE_PREMIUM = 1.1;    // EUR 1.1M inclusive/universal-design cliff vs re-skin
            this.PAYBACK_HURDLE = 30;        // CFO payback hurdle (months)
            this.HURDLE_INTENT = 25;         // 25% internal purchase-intent hurdle
            this.FAILED_INTENT = 8;          // 8% purchase intent of the failed concept
            this.SERVICEABLE = 90;           // EUR 90M serviceable silver market

            // Concept truths.
            this.TRUE_DIAGNOSIS = `meaning`;
            this.TRUE_PRINCIPLES = `dignity`;
            this.TRUE_DESIGN = `inclusive`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    desire: 8,               // purchase intent %, starts at the failed concept's 8%
                    personal: 20,            // personal value to the older user (0–100)
                    societal: 15,            // societal value: inclusion, dignity, take-back (0–100)
                    payback: null,           // payback in months — not computable until R3 pricing
                    budgetUsed: 0,           // EUR M of the 4.0M launch budget committed
                    reskinned: false,        // repeated the failed concept in a new colour
                    servedEveryone: false,   // tried to serve both segments
                    designLedClaim: false,   // claimed design-led but design didn't change the product
                    segment: ``,
                    desireHistory: [8],
                    personalHistory: [20],
                    societalHistory: [15],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win (it re-skins, serves everyone, claims design-led).
                state.decisions = {
                    diagnosis: `features`,
                    principles: `safety`,
                    r1Conviction: 50,
                    segment: `both`,
                    position: `assist`,
                    focus: 50,
                    design: `reskin`,
                    designSpend: 1.3,
                    societalSpend: 1.3,
                    businessSpend: 1.4,
                    price: `low`,
                    proof: `surface`,
                    balance: `profit`,
                    rival: `features`,
                    decision: `go`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const pr = document.getElementById(`principlesInput`);
                const cv = document.getElementById(`r1ConvictionInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (pr) decisions.principles = pr.value;
                if (cv) decisions.r1Conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.r1Conviction) || decisions.r1Conviction < 0 || decisions.r1Conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 2) {
                const sg = document.getElementById(`segmentInput`);
                const ps = document.getElementById(`positionInput`);
                const fc = document.getElementById(`focusInput`);
                if (sg) decisions.segment = sg.value;
                if (ps) decisions.position = ps.value;
                if (fc) decisions.focus = parseInt(fc.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 3) {
                const de = document.getElementById(`designInput`);
                const dsp = document.getElementById(`designSpendInput`);
                const ssp = document.getElementById(`societalSpendInput`);
                const bsp = document.getElementById(`businessSpendInput`);
                const pi = document.getElementById(`priceInput`);
                if (de) decisions.design = de.value;
                if (dsp) decisions.designSpend = parseFloat(dsp.value);
                if (ssp) decisions.societalSpend = parseFloat(ssp.value);
                if (bsp) decisions.businessSpend = parseFloat(bsp.value);
                if (pi) decisions.price = pi.value;
                const parts = [decisions.designSpend, decisions.societalSpend, decisions.businessSpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.designSpend + decisions.societalSpend + decisions.businessSpend) * 10) / 10;
                if (Math.abs(total - this.LAUNCH_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
                // True inclusive design needs the EUR 1.1M cliff funded in the design line.
                if (decisions.design === `inclusive` && decisions.designSpend < this.INCLUSIVE_PREMIUM) {
                    warn(`warn_design_underfunded`); return false;
                }
            } else if (round === 4) {
                const pf = document.getElementById(`proofInput`);
                const bl = document.getElementById(`balanceInput`);
                const rv = document.getElementById(`rivalInput`);
                const dc = document.getElementById(`decisionInput`);
                if (pf) decisions.proof = pf.value;
                if (bl) decisions.balance = bl.value;
                if (rv) decisions.rival = rv.value;
                if (dc) decisions.decision = dc.value;
                if (!decisions.decision) { warn(`warn_decision_required`); return false; }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite, extracted so calculateResults and getPerformanceSummary agree.
            const desire = Math.round(ds.desire);
            const personal = Math.round(ds.personal);
            const societal = Math.round(ds.societal);
            const payback = ds.payback;
            const paybackScore = (payback === null) ? 0 :
                Math.max(0, Math.min(100, 100 - (payback - this.PAYBACK_HURDLE) * 2.5));
            return Math.round(
                Math.min(100, desire * 2.4) * 0.28 + personal * 0.26 + societal * 0.24 + paybackScore * 0.22
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let desireDelta = 0, personalDelta = 0, societalDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the design failure as MEANING, not engineering (Common Error 1).
                switch (d.diagnosis) {
                    case `meaning`: desireDelta += 6; personalDelta += 10; societalDelta += 4; coachKey = `coach_r1_meaning`; break;
                    case `features`: desireDelta -= 3; personalDelta -= 4; coachKey = `coach_r1_features`; break;
                    case `price`: desireDelta += 1; coachKey = `coach_r1_price`; break;
                    case `awareness`: desireDelta -= 1; coachKey = `coach_r1_awareness`; break;
                }

                // Name the design principles — dignity/desirability first, not safety/assistance.
                switch (d.principles) {
                    case `dignity`: desireDelta += 5; personalDelta += 8; societalDelta += 6; if (d.diagnosis === `meaning`) coachKey = `coach_r1_sharp`; break;
                    case `safety`: desireDelta -= 4; personalDelta -= 2; coachKey = `coach_r1_safety`; break;
                    case `simplicity`: desireDelta -= 2; personalDelta += 1; break;
                    case `tech`: desireDelta -= 3; coachKey = `coach_r1_tech`; break;
                }

                // Conviction in the meaning diagnosis — carries the board.
                if (d.r1Conviction >= 60) { personalDelta += 4; societalDelta += 2; }
                else if (d.r1Conviction <= 25) { desireDelta -= 3; coachKey = `coach_r1_lowconviction`; }

                summaryKey = (d.diagnosis === `meaning` && d.principles === `dignity`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose ONE identity-driven segment (Common Error 2: serve everyone).
                ds.segment = d.segment;
                const f = d.focus / 100;

                switch (d.segment) {
                    case `active`:
                        desireDelta += 8; personalDelta += 5; societalDelta += 2; coachKey = `coach_r2_active`; break;
                    case `supported`:
                        desireDelta += 4; personalDelta += 6; societalDelta += 5; coachKey = `coach_r2_supported`; break;
                    case `staged`:
                        desireDelta += 6; personalDelta += 5; societalDelta += 5; coachKey = `coach_r2_staged`; break;
                    case `both`:
                        ds.servedEveryone = true;
                        desireDelta -= 8; personalDelta -= 5; societalDelta -= 2; coachKey = `coach_r2_both`; break;
                }

                // Positioning must match the job-to-be-done (identity for Active Agers).
                if (d.segment === `active` || d.segment === `staged`) {
                    if (d.position === `livewell`) { desireDelta += 6; personalDelta += 4; }
                    else if (d.position === `medical`) { desireDelta -= 7; personalDelta -= 4; coachKey = `coach_r2_medical`; }
                    else if (d.position === `assist`) { desireDelta -= 4; coachKey = `coach_r2_mismatch`; }
                } else if (d.segment === `supported`) {
                    if (d.position === `assist`) { personalDelta += 4; societalDelta += 2; }
                    else if (d.position === `medical`) { desireDelta -= 3; }
                }

                // Focus rewards discipline; low focus = averaging across needs.
                if (d.segment !== `both`) {
                    if (f >= 0.6) { desireDelta += 5; personalDelta += 3; }
                    else if (f <= 0.25) { desireDelta -= 4; coachKey = `coach_r2_lowfocus`; }
                }

                summaryKey = (d.segment !== `both` && d.focus >= 50) ? `sum_r2_good` :
                             (d.segment === `both` ? `sum_r2_everyone` : `sum_r2_weak`);
            } else if (round === 3) {
                // The central design decision and the EUR 1.1M cliff (Common Error 3: re-skin).
                switch (d.design) {
                    case `inclusive`:
                        desireDelta += 14; personalDelta += 12; societalDelta += 10; coachKey = `coach_r3_inclusive`; break;
                    case `reskin`:
                        ds.reskinned = true;
                        desireDelta -= 10; personalDelta -= 6; societalDelta -= 4; coachKey = `coach_r3_reskin`; break;
                    case `hybrid`:
                        desireDelta += 5; personalDelta += 4; societalDelta += 3; coachKey = `coach_r3_hybrid`; break;
                }

                // Allocation across the three value axes — each line buys its own axis.
                const dsp = d.designSpend, ssp = d.societalSpend, bsp = d.businessSpend;
                desireDelta += dsp * 4 - 4;             // design depth drives desirability (baseline ~1.0M)
                societalDelta += ssp * 7;               // co-design, accessibility, take-back drive societal value
                personalDelta += dsp * 2 + ssp * 2;     // dignity from both depth and co-design

                // Common Error 4a: strip social value to hit payback.
                if (ssp < 0.5) { societalDelta -= 6; coachKey = `coach_r3_nosocial`; }
                // Common Error 4b: over-invest in impact with no business engine.
                if (bsp < 0.5) { coachKey = `coach_r3_nobusiness`; }

                // Price point — sets margin per unit and therefore payback.
                let unitMargin, demandFactor;
                if (d.price === `premium`) { unitMargin = 170; demandFactor = 0.85; }
                else if (d.price === `mid`) { unitMargin = 95; demandFactor = 1.0; }
                else { unitMargin = 45; demandFactor = 1.15; }   // low price: thin margin, payback blows out

                // Compute payback (months). Higher desire & business spend lift demand;
                // re-skin and serve-everyone suppress it; thin margins stretch payback.
                const desireNow = Math.max(1, ds.desire + desireDelta);
                const intentFactor = desireNow / this.HURDLE_INTENT;     // ~1.0 at the 25% hurdle
                const channelFactor = 0.6 + bsp * 0.45;                  // business spend builds the channel
                const everyonePenalty = ds.servedEveryone ? 0.7 : 1.0;
                const reskinPenalty = ds.reskinned ? 0.65 : 1.0;

                const monthlyContribution = unitMargin * demandFactor * intentFactor *
                                            channelFactor * everyonePenalty * reskinPenalty;
                // Recover the full EUR 4.0M launch outlay (in EUR) from monthly contribution.
                let payback = (this.LAUNCH_BUDGET * 1000000) / Math.max(1, monthlyContribution * 1000);
                payback = Math.round(payback);
                payback = Math.max(8, Math.min(120, payback));
                ds.payback = payback;

                if (d.price === `low`) coachKey = ds.reskinned ? coachKey : `coach_r3_lowprice`;

                summaryKey = (d.design === `inclusive` && ssp >= 0.8 && bsp >= 0.8) ? `sum_r3_good` :
                             (d.design === `reskin` ? `sum_r3_reskin` : `sum_r3_weak`);
                spend = this.LAUNCH_BUDGET;             // the full budget is committed at the allocation step
            } else if (round === 4) {
                // Defend the design-led claim and the three-value balance (Common Errors 4 & 5).
                switch (d.proof) {
                    case `product`: desireDelta += 8; personalDelta += 6; societalDelta += 5; coachKey = `coach_r4_product`; break;
                    case `surface`: desireDelta -= 2; coachKey = `coach_r4_surface`; break;
                    case `claim`: ds.designLedClaim = true; desireDelta -= 6; personalDelta -= 4; coachKey = `coach_r4_claim`; break;
                }

                // The three-value balance: reinforce, profit-only, or impact-only.
                switch (d.balance) {
                    case `reinforce`: desireDelta += 6; personalDelta += 6; societalDelta += 6; if (d.proof === `product`) coachKey = `coach_r4_reinforce`; break;
                    case `profit`: societalDelta -= 10; personalDelta -= 4; coachKey = `coach_r4_profit`; break;
                    case `impact`:
                        societalDelta += 6;
                        if (ds.payback !== null) { ds.payback = Math.min(120, ds.payback + 18); }   // impact-only stretches payback
                        coachKey = `coach_r4_impact`; break;
                }

                // Beat the rival on meaning, not features or price.
                switch (d.rival) {
                    case `meaning`: desireDelta += 6; personalDelta += 3; break;
                    case `features`: desireDelta -= 4; coachKey = `coach_r4_rivalfeatures`; break;
                    case `price`:
                        desireDelta -= 2;
                        if (ds.payback !== null) { ds.payback = Math.min(120, ds.payback + 10); }    // price war erodes margin
                        coachKey = `coach_r4_rivalprice`; break;
                }

                summaryKey = (d.proof === `product` && d.balance === `reinforce` && d.rival === `meaning` && d.decision === `go`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the full EUR 4.0M is metered once, at the R3 allocation.
            ds.budgetUsed = Math.min(this.LAUNCH_BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas. Desirability is a purchase-intent %; the others are 0–100.
            ds.desire = Math.max(0, Math.min(100, Math.round(ds.desire + desireDelta)));
            ds.personal = Math.max(0, Math.min(100, Math.round(ds.personal + personalDelta)));
            ds.societal = Math.max(0, Math.min(100, Math.round(ds.societal + societalDelta)));

            ds.desireHistory.push(ds.desire);
            ds.personalHistory.push(ds.personal);
            ds.societalHistory.push(ds.societal);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                desire: ds.desire,
                desireDelta: Math.round(desireDelta),
                personal: ds.personal,
                personalDelta: Math.round(personalDelta),
                societal: ds.societal,
                societalDelta: Math.round(societalDelta),
                payback: ds.payback,
                budgetUsed: ds.budgetUsed,
                reskinned: ds.reskinned,
                servedEveryone: ds.servedEveryone,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€2.4M" (symbol before), Spanish "2,4 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        _fmtPayback(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v === null || v === undefined) return `—`;
            return `${Math.round(v)} ${t(`unit_months`)}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`desireDisplay`, `domainState.desire`, (v) => {
                const card = document.querySelector(`.lumieresim-card-desire`);
                if (card) {
                    card.classList.toggle(`lumieresim-desire-high`, Number(v) >= self.HURDLE_INTENT);
                    card.classList.toggle(`lumieresim-desire-low`, Number(v) < self.FAILED_INTENT + 4);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`personalDisplay`, `domainState.personal`, (v) => Math.round(Number(v)));
            uiManager.bind(`societalDisplay`, `domainState.societal`, (v) => Math.round(Number(v)));
            uiManager.bind(`paybackDisplay`, `domainState.payback`, (v) => {
                const card = document.querySelector(`.lumieresim-card-payback`);
                if (card) {
                    const has = (v !== null && v !== undefined);
                    card.classList.toggle(`lumieresim-payback-good`, has && Number(v) <= self.PAYBACK_HURDLE);
                    card.classList.toggle(`lumieresim-payback-bad`, has && Number(v) > self.PAYBACK_HURDLE);
                }
                return self._fmtPayback(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.LAUNCH_BUDGET);
            });

            // R1 conviction slider readout.
            const cv = document.getElementById(`r1ConvictionInput`);
            const cvReadout = document.getElementById(`r1ConvictionReadout`);
            if (cv && cvReadout) {
                cvReadout.textContent = cv.value;
                cv.addEventListener(`input`, function() { cvReadout.textContent = cv.value; });
            }

            // R2 focus slider readout.
            const fc = document.getElementById(`focusInput`);
            const fcReadout = document.getElementById(`focusReadout`);
            if (fc && fcReadout) {
                fcReadout.textContent = fc.value;
                fc.addEventListener(`input`, function() { fcReadout.textContent = fc.value; });
            }

            // R3 launch-budget live total (must hit EUR 4.0M).
            const allocIds = [`designSpendInput`, `societalSpendInput`, `businessSpendInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.lumieresim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.LAUNCH_BUDGET) > 0.001) ? `#c2402d` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
