        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.desireHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                lumiereChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.desireHistory },
                        { data: ds.personalHistory },
                        { data: ds.societalHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const desire = Math.round(ds.desire);
            const personal = Math.round(ds.personal);
            const societal = Math.round(ds.societal);
            const payback = ds.payback;

            // v1.1.0 — reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const desirable = desire >= this.HURDLE_INTENT;
            const viable = (payback !== null && payback <= this.PAYBACK_HURDLE);
            const inclusive = societal >= 55 && personal >= 55;
            const designLed = !ds.reskinned && !ds.designLedClaim;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_trap`;
            if (desirable && viable && inclusive && designLed && composite >= 75) tierKey = `grade_win`;
            else if (desirable && designLed && inclusive) tierKey = `grade_fragile`;
            else if (ds.reskinned || ds.servedEveryone) tierKey = `grade_failed`;
            else if (inclusive && !viable) tierKey = `grade_unprofitable`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (desirable && viable && inclusive && designLed) insights.push(window.mySimulation.t(`insight_win`));
            else if (ds.reskinned) insights.push(window.mySimulation.t(`insight_reskin`));
            else if (ds.servedEveryone) insights.push(window.mySimulation.t(`insight_everyone`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!desirable) insights.push(window.mySimulation.t(`insight_undesirable`));
            else if (desire >= 35) insights.push(window.mySimulation.t(`insight_desirable`));
            if (payback !== null && payback > this.PAYBACK_HURDLE) insights.push(window.mySimulation.t(`insight_payback`));
            if (societal < 40) insights.push(window.mySimulation.t(`insight_lowsocial`));
            if (ds.designLedClaim) insights.push(window.mySimulation.t(`insight_claimonly`));
            if (desirable && viable && inclusive && designLed) insights.push(window.mySimulation.t(`insight_threevalue`));

            return {
                desire: desire,
                personal: personal,
                societal: societal,
                payback: payback,
                desirable: desirable,
                viable: viable,
                inclusive: inclusive,
                designLed: designLed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="lum-cm"><p class="lum-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="lum-cm-chip ` + (ok ? `lum-cm-ok` : `lum-cm-no`) + `">` +
                `<span class="lum-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="lum-cm-kpi"><div class="lum-cm-kpi-val">` + val +
                `</div><div class="lum-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="lum-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="lum-cm">` +
  `<div class="lum-cm-head">` +
    `<div class="lum-cm-score"><div class="lum-cm-score-num">` + Math.round(s.composite) +
       `<span class="lum-cm-score-den">/100</span></div>` +
       `<div class="lum-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="lum-cm-verdict"><div class="lum-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="lum-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="lum-cm-section"><div class="lum-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="lum-cm-chips">` + chip(!!s.desirable, t(`cm_t_desire`)) + chip(!!s.viable, t(`cm_t_viable`)) +
      chip(!!s.inclusive, t(`cm_t_inclusive`)) + chip(!!s.designLed, t(`cm_t_designled`)) + `</div></div>` +
  `<div class="lum-cm-section"><div class="lum-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="lum-cm-kpis">` +
      kpi(t(`col_desire`), Math.round(s.desire) + `%`, t(`cm_sub_desire`)) +
      kpi(t(`col_personal`), Math.round(s.personal), t(`cm_sub_personal`)) +
      kpi(t(`col_societal`), Math.round(s.societal), t(`cm_sub_societal`)) +
      kpi(t(`col_payback`), this._fmtPayback(s.payback), t(`cm_sub_payback`)) +
    `</div></div>` +
  (insights ? `<div class="lum-cm-section"><div class="lum-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="lum-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.reskinned) return window.mySimulation.t(`hint_reskin`);
            if (ds.servedEveryone) return window.mySimulation.t(`hint_everyone`);
            if (ds.payback !== null && ds.payback > this.PAYBACK_HURDLE && state.currentPeriod >= 3) return window.mySimulation.t(`hint_payback`);
            if (state.currentPeriod >= 2 && ds.desire < this.HURDLE_INTENT) return window.mySimulation.t(`hint_desire`);
            if (ds.designLedClaim) return window.mySimulation.t(`hint_claim`);
            if (ds.desire >= this.HURDLE_INTENT && ds.societal >= 55 && ds.personal >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.desire`, label: `Desire`, i18nKey: `col_desire`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.personal`, label: `Personal`, i18nKey: `col_personal`, formatter: (v) => Math.round(v) },
                { key: `results.societal`, label: `Societal`, i18nKey: `col_societal`, formatter: (v) => Math.round(v) },
                { key: `results.payback`, label: `Payback`, i18nKey: `col_payback`, formatter: (v) => self._fmtPayback(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    grade_win:              `Design-Led Longevity Win`,
                    grade_fragile:          `Meaningful but Fragile P&L`,
                    grade_failed:           `Repeated the Failure`,
                    grade_unprofitable:     `Beautiful but Unprofitable`,
